#pragma once

#include <stddef.h>

typedef struct
{
    const char *stem;
    const char *text;
} sage_text_entry_t;

// Generated by tools/gen_voicelines_text.ps1 into the build dir.
extern const sage_text_entry_t sage_text_table[];
extern const size_t sage_text_table_count;

// Resolve a voiceline path like "0:/voicelines/much_later.wav" to the
// spoken line of text for on-screen display. Returns NULL if the stem
// isn't in the table (unknown voicelines just don't get captions).
const char *sage_text_from_path(const char *path);
